CREATE COLUMN TABLE "TEST_AP"."CTG1" ("CTGCode" SMALLINT CS_INT NOT NULL , "IntsNo" SMALLINT CS_INT NOT NULL , "InstMonth" SMALLINT CS_INT DEFAULT 0 NOT NULL , "InstDays" SMALLINT CS_INT DEFAULT 0 NOT NULL , "InstPrcnt" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("CTGCode", "IntsNo")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "CTG1_ABS_ENTRY" ON "TEST_AP"."CTG1" ( "CTGCode" ASC, "InstMonth" ASC, "InstDays" ASC )